CREATE TABLE draw_document(id INTEGER PRIMARY KEY, schema TEXT NOT NULL, artifact_id TEXT NOT NULL, title TEXT);
CREATE TABLE draw_scalar(id INTEGER PRIMARY KEY, value REAL, bits INTEGER NOT NULL, class TEXT NOT NULL);
CREATE TABLE draw_artboard(id INTEGER PRIMARY KEY REFERENCES draw_document(id), width INTEGER NOT NULL REFERENCES draw_scalar(id), height INTEGER NOT NULL REFERENCES draw_scalar(id));
CREATE TABLE draw_asset(id INTEGER PRIMARY KEY, document INTEGER NOT NULL REFERENCES draw_document(id), ordinal INTEGER NOT NULL, key TEXT NOT NULL, width INTEGER NOT NULL CHECK(width BETWEEN 0 AND 4294967295), height INTEGER NOT NULL CHECK(height BETWEEN 0 AND 4294967295));
CREATE TABLE draw_asset_sample(id INTEGER PRIMARY KEY, asset INTEGER NOT NULL REFERENCES draw_asset(id), ordinal INTEGER NOT NULL, r INTEGER NOT NULL CHECK(r BETWEEN 0 AND 255), g INTEGER NOT NULL CHECK(g BETWEEN 0 AND 255), b INTEGER NOT NULL CHECK(b BETWEEN 0 AND 255), a INTEGER NOT NULL CHECK(a BETWEEN 0 AND 255));
CREATE TABLE draw_layer(id INTEGER PRIMARY KEY, document INTEGER REFERENCES draw_document(id), parent INTEGER REFERENCES draw_layer(id), ordinal INTEGER NOT NULL, kind TEXT NOT NULL, layer_id TEXT NOT NULL, name TEXT NOT NULL, visible INTEGER NOT NULL, locked INTEGER NOT NULL, opacity INTEGER NOT NULL REFERENCES draw_scalar(id), blend_mode TEXT NOT NULL, fill_rule TEXT NOT NULL);
CREATE TABLE draw_transform(id INTEGER PRIMARY KEY REFERENCES draw_layer(id), x INTEGER NOT NULL REFERENCES draw_scalar(id), y INTEGER NOT NULL REFERENCES draw_scalar(id), scale_x INTEGER NOT NULL REFERENCES draw_scalar(id), scale_y INTEGER NOT NULL REFERENCES draw_scalar(id), shear INTEGER NOT NULL REFERENCES draw_scalar(id), rotation INTEGER NOT NULL REFERENCES draw_scalar(id));
CREATE TABLE draw_shape(id INTEGER PRIMARY KEY REFERENCES draw_layer(id), shape_kind TEXT NOT NULL);
CREATE TABLE draw_rect(id INTEGER PRIMARY KEY REFERENCES draw_shape(id), x INTEGER NOT NULL REFERENCES draw_scalar(id), y INTEGER NOT NULL REFERENCES draw_scalar(id), width INTEGER NOT NULL REFERENCES draw_scalar(id), height INTEGER NOT NULL REFERENCES draw_scalar(id));
CREATE TABLE draw_ellipse(id INTEGER PRIMARY KEY REFERENCES draw_shape(id), cx INTEGER NOT NULL REFERENCES draw_scalar(id), cy INTEGER NOT NULL REFERENCES draw_scalar(id), rx INTEGER NOT NULL REFERENCES draw_scalar(id), ry INTEGER NOT NULL REFERENCES draw_scalar(id));
CREATE TABLE draw_circle(id INTEGER PRIMARY KEY REFERENCES draw_shape(id), cx INTEGER NOT NULL REFERENCES draw_scalar(id), cy INTEGER NOT NULL REFERENCES draw_scalar(id), r INTEGER NOT NULL REFERENCES draw_scalar(id));
CREATE TABLE draw_line(id INTEGER PRIMARY KEY REFERENCES draw_shape(id), x1 INTEGER NOT NULL REFERENCES draw_scalar(id), y1 INTEGER NOT NULL REFERENCES draw_scalar(id), x2 INTEGER NOT NULL REFERENCES draw_scalar(id), y2 INTEGER NOT NULL REFERENCES draw_scalar(id));
CREATE TABLE draw_polygon(id INTEGER PRIMARY KEY REFERENCES draw_shape(id));
CREATE TABLE draw_polygon_point(id INTEGER PRIMARY KEY, polygon INTEGER NOT NULL REFERENCES draw_polygon(id), ordinal INTEGER NOT NULL, x INTEGER NOT NULL REFERENCES draw_scalar(id), y INTEGER NOT NULL REFERENCES draw_scalar(id));
CREATE TABLE draw_path(id INTEGER PRIMARY KEY REFERENCES draw_layer(id));
CREATE TABLE draw_segment(id INTEGER PRIMARY KEY, path INTEGER NOT NULL REFERENCES draw_path(id), ordinal INTEGER NOT NULL, kind TEXT NOT NULL);
CREATE TABLE draw_segment_to(id INTEGER PRIMARY KEY REFERENCES draw_segment(id), x INTEGER NOT NULL REFERENCES draw_scalar(id), y INTEGER NOT NULL REFERENCES draw_scalar(id));
CREATE TABLE draw_segment_quad(id INTEGER PRIMARY KEY REFERENCES draw_segment(id), x INTEGER NOT NULL REFERENCES draw_scalar(id), y INTEGER NOT NULL REFERENCES draw_scalar(id));
CREATE TABLE draw_segment_cubic(id INTEGER PRIMARY KEY REFERENCES draw_segment(id), x1 INTEGER NOT NULL REFERENCES draw_scalar(id), y1 INTEGER NOT NULL REFERENCES draw_scalar(id), x2 INTEGER NOT NULL REFERENCES draw_scalar(id), y2 INTEGER NOT NULL REFERENCES draw_scalar(id));
CREATE TABLE draw_segment_arc(id INTEGER PRIMARY KEY REFERENCES draw_segment(id), rx INTEGER NOT NULL REFERENCES draw_scalar(id), ry INTEGER NOT NULL REFERENCES draw_scalar(id), rotation INTEGER NOT NULL REFERENCES draw_scalar(id), large_arc INTEGER NOT NULL, sweep INTEGER NOT NULL);
CREATE TABLE draw_text(id INTEGER PRIMARY KEY REFERENCES draw_layer(id), x INTEGER NOT NULL REFERENCES draw_scalar(id), y INTEGER NOT NULL REFERENCES draw_scalar(id), content TEXT NOT NULL, size INTEGER NOT NULL REFERENCES draw_scalar(id));
CREATE TABLE draw_image(id INTEGER PRIMARY KEY REFERENCES draw_layer(id), image_key TEXT NOT NULL, width INTEGER NOT NULL REFERENCES draw_scalar(id), height INTEGER NOT NULL REFERENCES draw_scalar(id));
CREATE TABLE draw_group(id INTEGER PRIMARY KEY REFERENCES draw_layer(id), isolation INTEGER NOT NULL);
CREATE TABLE draw_boolean(id INTEGER PRIMARY KEY REFERENCES draw_layer(id), operation TEXT NOT NULL);
CREATE TABLE draw_boolean_child(id INTEGER PRIMARY KEY, owner INTEGER NOT NULL REFERENCES draw_boolean(id), ordinal INTEGER NOT NULL, layer_id TEXT NOT NULL);
CREATE TABLE draw_trace(id INTEGER PRIMARY KEY REFERENCES draw_layer(id), source_key TEXT NOT NULL, threshold INTEGER NOT NULL REFERENCES draw_scalar(id), simplify_epsilon INTEGER NOT NULL REFERENCES draw_scalar(id));
CREATE TABLE draw_fill(id INTEGER PRIMARY KEY REFERENCES draw_layer(id), kind TEXT NOT NULL);
CREATE TABLE draw_fill_solid(id INTEGER PRIMARY KEY REFERENCES draw_fill(id), r INTEGER NOT NULL REFERENCES draw_scalar(id), g INTEGER NOT NULL REFERENCES draw_scalar(id), b INTEGER NOT NULL REFERENCES draw_scalar(id), a INTEGER NOT NULL REFERENCES draw_scalar(id));
CREATE TABLE draw_fill_linear(id INTEGER PRIMARY KEY REFERENCES draw_fill(id), x1 INTEGER NOT NULL REFERENCES draw_scalar(id), y1 INTEGER NOT NULL REFERENCES draw_scalar(id), x2 INTEGER NOT NULL REFERENCES draw_scalar(id), y2 INTEGER NOT NULL REFERENCES draw_scalar(id));
CREATE TABLE draw_fill_radial(id INTEGER PRIMARY KEY REFERENCES draw_fill(id), cx INTEGER NOT NULL REFERENCES draw_scalar(id), cy INTEGER NOT NULL REFERENCES draw_scalar(id), r INTEGER NOT NULL REFERENCES draw_scalar(id));
CREATE TABLE draw_gradient_stop(id INTEGER PRIMARY KEY, fill INTEGER NOT NULL REFERENCES draw_fill(id), ordinal INTEGER NOT NULL, offset INTEGER NOT NULL REFERENCES draw_scalar(id), r INTEGER NOT NULL REFERENCES draw_scalar(id), g INTEGER NOT NULL REFERENCES draw_scalar(id), b INTEGER NOT NULL REFERENCES draw_scalar(id), a INTEGER NOT NULL REFERENCES draw_scalar(id));
CREATE TABLE draw_stroke(id INTEGER PRIMARY KEY REFERENCES draw_layer(id), r INTEGER NOT NULL REFERENCES draw_scalar(id), g INTEGER NOT NULL REFERENCES draw_scalar(id), b INTEGER NOT NULL REFERENCES draw_scalar(id), a INTEGER NOT NULL REFERENCES draw_scalar(id), width INTEGER NOT NULL REFERENCES draw_scalar(id), cap TEXT NOT NULL, join_kind TEXT NOT NULL, has_dash INTEGER NOT NULL);
CREATE TABLE draw_stroke_dash(id INTEGER PRIMARY KEY, stroke INTEGER NOT NULL REFERENCES draw_stroke(id), ordinal INTEGER NOT NULL, value INTEGER NOT NULL REFERENCES draw_scalar(id));
